int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));
    size_t path_len = strlen((const char *)buffer + sizeof(git_index_entry));
    size_t total_size = sizeof(git_index_entry) + path_len + 1;

    if (buffer_size < total_size) {
        free(entry);
        return -1;
    }

    if (last && *last) {
        size_t full_path_len = strlen((const char *)buffer + sizeof(git_index_entry)) + strlen(last) + 2;
        char *full_path = (char *)malloc(full_path_len);
        if (!full_path) {
            free(entry);
            return -1;
        }
        snprintf(full_path, full_path_len, "%s/%s", (const char *)buffer + sizeof(git_index_entry), last);
        entry->path = full_path;
    } else {
        entry->path = strdup((const char *)buffer + sizeof(git_index_entry));
    }

    *out = entry;
    *out_size = total_size;
    return 0;
}

