        entry->path = (char *)last;
    }

    *out = entry;
    *out_size = sizeof(git_index_entry) + path_size;

    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    if (entry->path_length + 1 > buffer_size - sizeof(git_index_entry)) {
        free(entry);
        return -1;
    }

    char *path = (char *)malloc(entry->path_length + 1);
    if (!path) {
        free(entry);
        return -1;
    }

    memcpy(path, (char *)buffer + sizeof(git_index_entry), entry->path_length);
    path[entry->path_length] = '\0';

    if (last != NULL) {
        char *full_path = (char *)malloc(strlen(path) + strlen(last) + 2);
        if (!full_path) {
            free(path);
            free(entry);
            return -1;
        }

        snprintf(full_path, strlen(path) + strlen(last) + 2, "%s/%s", path, last);
        free(path);
        path = full_path;
    }

    entry->path = path;
    *out = entry;
    *out_size = sizeof(git_index_entry) + entry->path_length;

    return 0;
}

int git_index_read_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (entry == NULL) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    if (entry->path && last) {
        size_t path_len = strlen(entry->path);
        size_t last_len = strlen(last);
        char *full_path = (char *)malloc(path_len + last_len + 1);

        if (full_path == NULL) {
            free(entry);
            return -1;
        }

        strcpy(full_path, last);
        strcat(full_path, entry->path);
        free(entry->path);
        entry->path = full_path;
    }

    *out = entry;
    *out_size = sizeof(git_index_entry);
    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    *out_size = sizeof(git_index_entry);
    *out = (git_index_entry *)malloc(*out_size);
    if (!*out) {
        return -1;
    }

    memcpy(*out, buffer, *out_size);

    size_t path_len = strlen(last) + 1;
    size_t entry_path_size = path_len + 1;

    char *path = (char *)malloc(entry_path_size);
    if (!path) {
        free(*out);
        *out = NULL;
        return -1;
    }

    snprintf(path, entry_path_size, "%s", last);
    (*out)->path = path;

    return 0;
}
